# ---------------------------------------------------------------- four exercises on the basic analyses
def _anq(rows, heads, cols, widths):
    """Given figures in A:C, answers in the columns of heads; rows: [(label, values...)]."""
    d, g, f, st = {'A1': heads[0]}, {}, {}, {}
    for j, h in enumerate(heads[1:]): d[f'{chr(66 + j)}1'] = h
    for j in range(len(heads)): st[f'{chr(65 + j)}1'] = {'fill': '#e1e7f8', 'b': True}
    for i, row in enumerate(rows):
        r = 2 + i; d[f'A{r}'] = row[0]
        for j, v in enumerate(row[1:]): g[f'{chr(66 + j)}{r}'] = v; f[f'{chr(66 + j)}{r}'] = 'acc0'
    return d, g, f, st


_om = [('הכנסות מתיקונים', 150000), ('חלקי חילוף שנצרכו', 14000), ('שכר טכנאים', 50000), ('שכר דירה', 24000), ('רווח תפעולי', 62000), ('רווח נקי', 46200)]
_d, _g, _f, _s = _anq(_om, ['שורה בדוח', 'ש״ח', '% מההכנסות'], 2, None)
_sol = {f'C{2 + i}': f'=B{2 + i}/B$2' for i in range(len(_om))}
for _a in _sol: _f[_a] = 'pct1'
QT('t-9', 'תרגול עצמי 1', 'מעבדת עומר: ניתוח אנכי', ['בשנת 2027 היו למעבדת התיקונים של עומר בע״מ הכנסות של 150,000 ש״ח. ההוצאות התפעוליות: חלקי חילוף שנצרכו 14,000, שכר טכנאים 50,000 ושכר דירה 24,000. הרווח התפעולי 62,000, והרווח הנקי 46,200.',
   '<b>נדרש:</b> חשבו כל שורה כאחוז מההכנסות. מה שיעור הרווח הנקי של עומר, ואיך הוא בהשוואה ל-20.5% של קפה נועה?'],
   'בעמודה C: כל שורה חלקי ההכנסות.', STSHEET(_d, _g, _sol, [dict(cells={a: v}, note=f'{XL(v)}: {n} חלקי ההכנסות.', sel=a) for (a, v), (n, _) in zip(_sol.items(), _om)], [320, 200, 200], _f, _s), one=True, big=True,
   hints=['=B2/B$2 בתא C2, וגוררים למטה.'], remind='=B3/B$2',
   more=MORE('למה לעומר שיעור רווח גבוה יותר?', ['עומר מוכר שירות: אין לו עלות של סחורה שנמכרה, רק חלקים קטנים (9.3% מההכנסות).', 'בקפה נועה עלות המכירות לבדה היא 45% מהמכירות. לכן מכל 100 שקלים נשארים לעומר 30.8, ולנועה 20.5.']),
   done='שיעור רווח תפעולי 41.3%, שיעור רווח נקי 30.8%.')

_rr = [('נכסים שוטפים', 109200, 217600), ('התחייבויות שוטפות', 8000, 17000), ('סך הנכסים', 154200, 337600), ('הון עצמי', 106200, 295600), ('רווח נקי', 46200, 123200)]
_d, _g, _f, _s = _anq(_rr, ['נתון, 2027', 'עומר', 'קפה נועה'], 3, None)
_d.update({'A7': 'יחס', 'B7': 'עומר', 'C7': 'קפה נועה', 'D7': 'איך מחשבים'}); _s['A7'] = _s['B7'] = _s['C7'] = _s['D7'] = {'fill': '#fff0c2', 'b': True}
_RT9 = [('יחס שוטף', '={c}2/{c}3', 'num2'), ('הון עצמי מסך הנכסים', '={c}5/{c}4', 'pct1'), ('תשואה על הנכסים (ROA)', '={c}6/{c}4', 'pct1'), ('תשואה על ההון (ROE)', '={c}6/{c}5', 'pct1')]
_HOW9 = ['נכסים שוטפים חלקי התחייבויות שוטפות', 'הון עצמי חלקי סך הנכסים', 'רווח נקי חלקי סך הנכסים', 'רווח נקי חלקי הון עצמי']
_sol, _stp = {}, []
for _i, (_n, _fx, _fm) in enumerate(_RT9):
    _r = 8 + _i; _d[f'A{_r}'] = _n; _d[f'D{_r}'] = _HOW9[_i]
    for _c in 'BC': _sol[f'{_c}{_r}'] = _fx.format(c=_c); _f[f'{_c}{_r}'] = _fm
    _stp.append(dict(cells={f'B{_r}': _fx.format(c='B'), f'C{_r}': _fx.format(c='C')}, note=f'<b>{_n}:</b> {XL(_fx.format(c="B"))}, ובאותה דרך לקפה נועה.', sel=f'B{_r}'))
QT('t-10', 'תרגול עצמי 2', 'עומר מול קפה נועה: ארבעה יחסים', ['בטבלה הנתונים של שתי החברות לשנת 2027, מהמאזנים ומדוחות רווח והפסד שערכנו.',
   '<b>נדרש:</b> חשבו לכל חברה יחס שוטף, הון עצמי מסך הנכסים, תשואה על הנכסים ותשואה על ההון. למי תשואה גבוהה יותר על ההון, ולמה, אם התשואה שלה על הנכסים נמוכה יותר?'],
   'כל יחס: שורה אחת חלקי שורה אחרת, באותה עמודה.', STSHEET(_d, _g, _sol, _stp, [300, 150, 150, 330], _f, _s), one=True, big=True,
   hints=['תשואה על ההון: =B6/B5. הון עצמי מסך הנכסים: =B5/B4.'], remind='=B6/B5',
   more=MORE('אותה תשואה על הנכסים, תשואה שונה על ההון', ['אצל עומר הבעלים מימנו רק 68.9% מהנכסים, והשאר הלוואה וספקים. אצל נועה הבעלים מימנו 87.6%.', 'כשחלק מהנכסים ממומן בכסף של אחרים, כל שקל של הבעלים ״מחזיק״ יותר נכסים. לכן אצל עומר התשואה על ההון, 43.5%, גבוהה מהתשואה על הנכסים, 30.0%.']),
   done='עומר: יחס שוטף 13.65, תשואה על ההון 43.5%. נועה: 12.80, ו-41.7%.')

_li = [('הכנסות', 30000, 42000), ('מוצרים שנצרכו', 2500, 3600), ('שכר דירה', 9000, 9600), ('חשמל', 600, 900), ('רווח נקי', 17900, 27900)]
assert 42000 - 3600 - 9600 - 900 == 27900 and 30000 - 2500 - 9000 - 600 == 17900
_d, _g, _f, _s = _anq(_li, ['שורה בדוח', 'שנת 2026', 'שנת 2027', 'שינוי בש״ח', 'שינוי ב-%'], 3, None)
_sol, _stp = {}, []
for _i, (_n, _a, _b) in enumerate(_li):
    _r = 2 + _i; _sol[f'D{_r}'] = f'=C{_r}-B{_r}'; _sol[f'E{_r}'] = f'=D{_r}/B{_r}'; _f[f'D{_r}'] = 'acc0'; _f[f'E{_r}'] = 'pct1'
    _stp.append(dict(cells={f'D{_r}': f'=C{_r}-B{_r}', f'E{_r}': f'=D{_r}/B{_r}'}, note=f'<b>{_n}:</b> {_b - _a:,} ש״ח, כלומר {(_b - _a) / _a * 100:.1f}%.', sel=f'D{_r}'))
