_d['A7'] = 'סך הנכסים'; _g['B7'] = 154200; _f['B7'] = 'acc0'; _s['A7'] = _s['B7'] = {'b': True, 'fill': '#f3f2f1'}
_sol = {f'C{2 + i}': f'=B{2 + i}/B$7' for i in range(len(_obs4))}
for _a in _sol: _f[_a] = 'pct1'
